class SpacedSeating {
  private seats: number[] = [];
  constructor(private n: number) {}

  sit(): number {
    const s = this.seats;
    if (s.length === 0) { s.push(0); return 0; }
    let best = s[0], chair = 0, at = 0;
    for (let i = 0; i + 1 < s.length; i++) {
      const d = (s[i + 1] - s[i]) >> 1;
      if (d > best) { best = d; chair = s[i] + d; at = i + 1; }
    }
    if (this.n - 1 - s[s.length - 1] > best) { chair = this.n - 1; at = s.length; }
    s.splice(at, 0, chair);
    return chair;
  }

  leave(chair: number): void {
    this.seats.splice(this.seats.indexOf(chair), 1);
  }
}

