  private next = new Map<number, number>();
  private prev = new Map<number, number>();
  private heap: number[][] = []; // [dist, chair, a, b]

  constructor(private n: number) {
    this.next.set(-1, n);
    this.prev.set(n, -1);
    this.push(-1, n);
  }

  private better(x: number[], y: number[]): boolean {
    return x[0] !== y[0] ? x[0] > y[0] : x[1] < y[1];
  }

  private push(a: number, b: number): void {
    const n = this.n;
    let s: number, d: number;
    if (a === -1 && b === n) { s = 0; d = n; }
    else if (a === -1) { if (b === 0) return; s = 0; d = b; }
    else if (b === n) { if (a === n - 1) return; s = n - 1; d = n - 1 - a; }
    else { if (b - a < 2) return; d = Math.floor((b - a) / 2); s = a + d; }
    const h = this.heap;
    h.push([d, s, a, b]);
    let i = h.length - 1;
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (!this.better(h[i], h[p])) break;
      [h[i], h[p]] = [h[p], h[i]];
      i = p;
    }
  }

  private pop(): number[] {
    const h = this.heap, top = h[0], last = h.pop()!;
    if (h.length) {
      h[0] = last;
      let i = 0;
      for (;;) {
        const l = 2 * i + 1, r = l + 1;
        let m = i;
        if (l < h.length && this.better(h[l], h[m])) m = l;
        if (r < h.length && this.better(h[r], h[m])) m = r;
        if (m === i) break;
        [h[i], h[m]] = [h[m], h[i]];
        i = m;
      }
    }
    return top;
  }

  sit(): number {
    let e = this.pop();
    while (this.next.get(e[2]) !== e[3]) e = this.pop(); // stale gap
    const [, s, a, b] = e;
    this.next.set(a, s); this.prev.set(s, a);
    this.next.set(s, b); this.prev.set(b, s);
    this.push(a, s);
    this.push(s, b);
    return s;
  }

  leave(chair: number): void {
    const a = this.prev.get(chair)!, b = this.next.get(chair)!;
    this.next.set(a, b); this.prev.set(b, a);
    this.next.delete(chair); this.prev.delete(chair);
    this.push(a, b);
  }
}

